using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using MazeRunner.Levels;

namespace MazeRunner.EditorTools
{
    /// <summary>
    /// Puts the moon (Assets/Art/Environment/Moon.png, generated by tools/make_moon.py) and a sky-gradient
    /// backdrop (SkyGradient.png) in the sky of Levels 1-3: one "SkyMoon" object per level plus the "SkyBackdrop"
    /// it stretches over the view, both unlit, drawn behind everything (sorting order -1000 / -1001, no collider), positioned on
    /// screen by <see cref="SkyMoon"/>. Running it again only updates the existing objects.
    /// Menu: Maze Runner > Add Sky Moon
    /// CLI:  Unity -batchmode -quit -projectPath . -executeMethod MazeRunner.EditorTools.SkyMoonSetup.RunFromCommandLine
    /// </summary>
    public static class SkyMoonSetup
    {
        private const string MoonPath = "Assets/Art/Environment/Moon.png";
        private const string SkyPath = "Assets/Art/Environment/SkyGradient.png";
        // Unlit, so 2D lights in the level never dim or tint the sky.
        private const string UnlitMaterialPath = "Packages/com.unity.render-pipelines.universal/Runtime/Materials/Sprite-Unlit-Default.mat";
        private static readonly string[] Levels =
        {
            "Assets/Scenes/Levels/Level1.unity",
            "Assets/Scenes/Levels/Level2.unity",
            "Assets/Scenes/Levels/Level3.unity",
        };

        [MenuItem("Maze Runner/Add Sky Moon")]
        public static bool Run()
        {
            var moon = ImportSprite(MoonPath, 512, true);
            var sky = ImportSprite(SkyPath, 256, false);
            var unlit = AssetDatabase.LoadAssetAtPath<Material>(UnlitMaterialPath);
            if (moon == null || sky == null || unlit == null) { Debug.LogError("[SkyMoon] missing moon/sky sprite or unlit material"); return false; }

            foreach (string path in Levels)
            {
                var scene = EditorSceneManager.OpenScene(path, OpenSceneMode.Single);
                var existing = Object.FindAnyObjectByType<SkyMoon>(FindObjectsInactive.Include);
                GameObject go = existing != null ? existing.gameObject : new GameObject("SkyMoon", typeof(SpriteRenderer), typeof(SkyMoon));
                go.transform.position = new Vector3(0f, 0f, 5f);
                var sr = go.GetComponent<SpriteRenderer>();
                sr.sprite = moon;
                sr.sharedMaterial = unlit;
                sr.sortingOrder = -1000;
                sr.color = Color.white;

                var so = new SerializedObject(go.GetComponent<SkyMoon>());
                // Sized in world units by SkyMoon, so it is a separate root object (not a child of the scaled moon).
                var bsr = so.FindProperty("backdrop").objectReferenceValue as SpriteRenderer;
                if (bsr == null) bsr = new GameObject("SkyBackdrop", typeof(SpriteRenderer)).GetComponent<SpriteRenderer>();
                bsr.transform.position = new Vector3(0f, 0f, 6f);
                bsr.sprite = sky;
                bsr.sharedMaterial = unlit;
                bsr.sortingOrder = -1001;

                so.FindProperty("viewportPosition").vector2Value = new Vector2(0.84f, 0.74f);
                so.FindProperty("screenHeightFraction").floatValue = 0.24f;
                so.FindProperty("narrowWidthFactor").floatValue = 1.25f;
                so.FindProperty("edgeMargin").floatValue = 0.65f;
                so.FindProperty("backdrop").objectReferenceValue = bsr;
                so.ApplyModifiedPropertiesWithoutUndo();

                EditorSceneManager.MarkSceneDirty(scene);
                EditorSceneManager.SaveScene(scene);
                Debug.Log("[SkyMoon] " + path + " ok");
            }
            return true;
        }

        private static Sprite ImportSprite(string path, int maxSize, bool mipmaps)
        {
            var importer = (TextureImporter)AssetImporter.GetAtPath(path);
            if (importer == null) return null;
            importer.textureType = TextureImporterType.Sprite;
            importer.spriteImportMode = SpriteImportMode.Single;
            importer.spritePixelsPerUnit = 100;
            importer.alphaIsTransparency = true;
            importer.mipmapEnabled = mipmaps;   // the moon is drawn well below 512px on phones; mips keep craters from shimmering
            importer.filterMode = FilterMode.Bilinear;
            importer.wrapMode = TextureWrapMode.Clamp;
            importer.maxTextureSize = maxSize;
            importer.textureCompression = TextureImporterCompression.Uncompressed;   // block compression bands the soft halo / gradient
            importer.SaveAndReimport();
            return AssetDatabase.LoadAssetAtPath<Sprite>(path);
        }

        public static void RunFromCommandLine()
        {
            bool ok;
            try { ok = Run(); }
            catch (System.Exception e) { Debug.LogException(e); ok = false; }
            EditorApplication.Exit(ok ? 0 : 1);
        }
    }
}
